from pathlib import Path
import json
import html

ROOT = Path(__file__).resolve().parent
def esc(value):
    if isinstance(value, (dict, list)):
        value = json.dumps(value, ensure_ascii=False, indent=2)
    return html.escape(str(value or ""))

def main():
    data = json.loads((ROOT / "storyboards.json").read_text(encoding="utf-8"))
    manifest_path = ROOT / "scene_manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8")) if manifest_path.exists() else {}
    images = manifest.get("images", [])
    overrides = {(x["concept_id"], x["cut_id"]): x["image_path"] for x in images}
    concepts = data["concepts"]
    summary, sections = [], []
    for index, c in enumerate(concepts, 1):
        cid = c["id"]
        shots = c["shots"]
        first = overrides.get((cid, shots[0]["id"]), shots[0]["image_file"])
        summary.append(f'''<a class="summary-card" href="#{cid}"><img src="{esc(first)}" alt="신규 {index}안 첫 프레임"><span class="kicker">신규 {index:02d} · {esc(c['purpose'])}</span><h2>{esc(c['title'])}</h2><p>{esc(c['logline'])}</p><small>{esc(c['duration_seconds'])}초 · {len(shots)}컷 · {esc(c['format'])}</small></a>''')
        cutcards = []
        for s in shots:
            src = overrides.get((cid, s["id"]), s["image_file"])
            title = f"신규 {index} / {s['id']} / {s['start']:g}–{s['end']:g}초"
            is_ending = s is shots[-1]
            overlay = ''
            if is_ending:
                ending_line = s['subtitle'].split('\n')[-1]
                title_left = 53 if cid == 'C05' else 43
                overlay = f'<div class="title-mock" style="left:{title_left}%"><small>2026년 품질팀</small><strong>AI 실행 결과<br>발표 대회</strong><em>{esc(ending_line)}</em></div>'
            frame_label = '자막 배치 예시 · 원본 PNG는 배경판' if is_ending else '첫 프레임 · 클릭하면 확대' 
            cutcards.append(f'''<article class="shot" id="{cid}-{s['id']}">
              <button class="frame" data-image="{esc(src)}" data-caption="{esc(title)}"><img src="{esc(src)}" alt="{esc(title)} 첫 프레임" loading="lazy">{overlay}<span>{frame_label}</span></button>
              <div class="shot-body"><div class="shot-top"><b>{esc(s['scene_id'])} · {esc(s['id'])}</b><span>{s['start']:g}–{s['end']:g}초 / {s['duration']:g}초</span></div>
              <h3>{esc(s['screen'])}</h3><p class="framing">{esc(s['framing'])}</p>
              <dl><dt>대사</dt><dd>{esc(s['dialogue']) or '없음'}</dd><dt>화면 자막</dt><dd>{esc(s['subtitle']) or '없음'}</dd><dt>소리·정적</dt><dd>{esc(s['sound'])}</dd><dt>전환</dt><dd>{esc(s['transition'])}</dd></dl>
              <details><summary>시작 상태 · 이어질 동작 · 연속성</summary><p><b>첫 프레임</b> {esc(s['first_frame'])}</p><p><b>이어질 동작</b> {esc(s['next_motion'])}</p><p><b>들어오는 상태</b> {esc(s['continuity_in'])}</p><p><b>나가는 상태</b> {esc(s['continuity_out'])}</p><p><b>의도</b> {esc(s['intent'])}</p><a href="{esc(src)}" download>PNG 원본</a></details></div></article>''')
        sections.append(f'''<section class="concept" id="{cid}"><header class="concept-head"><div class="kicker">신규 {index:02d} / {esc(c['purpose'])}</div><h2>{esc(c['title'])}</h2><p class="logline">{esc(c['logline'])}</p><div class="tags"><span>{esc(c['duration_seconds'])}초</span><span>{len(shots)}컷</span><span>B급 강도 {esc(c['bgrade_intensity'])}/5</span><span>제작 난이도 {esc(c['difficulty'])}</span></div><p><b>핵심 메시지</b> {esc(c['core_message'])}</p><p><b>웃음 구조</b> {esc(c['comedy_engine'])}</p><p><b>마지막 연결</b> {esc(c['final_action'])}</p><details><summary>연출 기준과 캐릭터</summary><p><b>대상·상영</b> {esc(c['audience'])}</p><p><b>첫 훅</b> {esc(c['hook'])}</p><p><b>3단 전개</b></p><pre>{esc(c['three_act'])}</pre><p><b>행사 정보</b> {esc(c['event_information'])}</p><p>{esc(c['visual_style'])}</p><pre>{esc(c['characters'])}</pre><p>{esc(c['continuity'])}</p><p><b>난이도 판단</b> {esc(c['difficulty_reason'])}</p><p><b>다른 안과의 차이</b> {esc(c['difference'])}</p></details></header><div class="shots">{''.join(cutcards)}</div><a class="back" href="#top">↑ 5안 비교로</a></section>''')
    nav = ''.join(f'<a href="#{c["id"]}">{i:02d} {esc(c["title"])}</a>' for i, c in enumerate(concepts, 1))
    count = sum(len(c["shots"]) for c in concepts)
    status = json.loads((ROOT / "delivery_status.json").read_text(encoding="utf-8")) if (ROOT / "delivery_status.json").exists() else {}
    status_text = "컷별 이미지·교차 검수 완료" if status.get("status") == "complete" else "제작·검수 중"
    document = '''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>B급 코미디 새 기획 5안 · 컷별 첫 프레임</title><style>
    :root{--ink:#20201d;--paper:#f6f1e7;--orange:#e74b22;--yellow:#f4ce44;--muted:#666456}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:'Malgun Gothic','Noto Sans KR',system-ui,sans-serif;line-height:1.65}a{color:inherit}button{font:inherit}header.hero{background:var(--ink);color:var(--paper);padding:64px max(24px,calc((100vw - 1320px)/2)) 40px}.hero h1{font-size:clamp(32px,5vw,68px);line-height:1.15;letter-spacing:-.065em;margin:14px 0 24px}.hero p{max-width:870px;color:#e5dfd2}.kicker{font-size:12px;letter-spacing:.1em;font-weight:800;color:var(--orange)}.hero .kicker{color:var(--yellow)}.status{display:inline-block;border:1px solid #8e8c7a;padding:6px 12px;border-radius:2px;font-size:12px}.hero .note{font-size:13px;color:#c5c1b6}.nav{position:sticky;top:0;background:#f6f1e7f5;z-index:2;border-bottom:1px solid #c4bdae;display:flex;gap:20px;padding:13px 24px;overflow-x:auto;backdrop-filter:blur(8px)}.nav a{white-space:nowrap;text-decoration:none;font-size:12px;font-weight:700}.nav a:hover{color:var(--orange)}main{max-width:1370px;padding:36px 24px 90px;margin:auto}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.summary-card{background:white;border:1px solid #d8d2c5;text-decoration:none;padding:0 20px 22px;box-shadow:4px 4px 0 #ddd6c5}.summary-card img{width:calc(100% + 40px);margin:0 -20px 16px;aspect-ratio:16/9;object-fit:cover}.summary-card h2{font-size:24px;letter-spacing:-.05em;line-height:1.3;margin:8px 0}.summary-card p{font-size:14px}.summary-card small{color:var(--muted)}.concept{padding-top:70px;scroll-margin-top:40px}.concept-head{max-width:1000px;border-top:5px solid var(--ink);padding:22px 0}.concept-head h2{font-size:clamp(30px,4vw,46px);line-height:1.25;letter-spacing:-.05em;margin:9px 0 15px}.logline{font-size:20px}.tags{display:flex;gap:8px;flex-wrap:wrap}.tags span{border:1px solid #aca591;padding:3px 10px;font-size:12px}.shots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:26px}.shot{scroll-margin-top:68px;background:#fff;border:1px solid #d8d2c5;break-inside:avoid}.frame{position:relative;width:100%;padding:0;border:0;display:block;background:#151513;cursor:zoom-in}.frame img{width:100%;aspect-ratio:16/9;object-fit:contain;display:block}.title-mock{position:absolute;left:43%;right:5%;top:18%;text-align:left;color:#172521;pointer-events:none}.title-mock small{display:block;font-size:clamp(10px,1vw,15px);font-weight:700}.title-mock strong{display:block;font-size:clamp(19px,2.4vw,35px);line-height:1.2;letter-spacing:-.05em;margin:6px 0 15px}.title-mock em{font-style:normal;display:block;font-size:clamp(9px,1vw,14px);font-weight:600}.frame span{position:absolute;bottom:9px;left:12px;background:#141411c9;color:white;padding:2px 7px;font-size:10px}.shot-body{padding:20px 22px}.shot-top{display:flex;justify-content:space-between;gap:12px;font-size:12px;color:var(--muted)}.shot-top b{color:var(--orange)}h3{font-size:18px;line-height:1.6;font-weight:700;margin:12px 0}.framing{font-size:12px;color:var(--muted)}dl{display:grid;grid-template-columns:74px 1fr;gap:6px 10px;font-size:13px}dt{font-weight:700}dd{margin:0;white-space:pre-wrap}details{border-top:1px solid #ddd8ce;padding-top:12px;margin-top:20px;font-size:12px}summary{cursor:pointer;font-weight:700}details p{white-space:pre-wrap}pre{font-family:inherit;white-space:pre-wrap;word-break:break-word;font-size:12px}.back{display:block;margin:25px 0;font-size:12px}.notes{margin-top:70px;border-top:3px solid var(--ink);padding-top:24px;font-size:13px}.notes a{margin-right:18px}dialog{padding:0;border:none;background:#141411;color:white;max-width:96vw;max-height:96vh}dialog::backdrop{background:#000c}dialog img{max-width:94vw;max-height:85vh;display:block;object-fit:contain}dialog footer{display:flex;align-items:center;justify-content:space-between;padding:10px 16px;gap:15px;font-size:12px}dialog button{background:white;border:0;padding:4px 14px;cursor:pointer}@media(max-width:900px){.summary{grid-template-columns:1fr 1fr}.shots{grid-template-columns:1fr}}@media(max-width:560px){.summary{grid-template-columns:1fr}.hero{padding-top:35px!important}.logline{font-size:17px}.shot-body{padding:16px}}@media print{.nav,.back,dialog{display:none}.hero{padding:25px!important;background:white!important;color:black!important}.hero p{color:black!important}.summary{grid-template-columns:repeat(2,1fr)}.shots{display:block}.shot{display:grid;grid-template-columns:42% 58%;margin-bottom:12px}.frame img{aspect-ratio:16/9}.frame span{display:none}.shot-body{padding:12px}.concept{break-before:page}h3{font-size:12px;margin:8px 0}dl{font-size:10px}details{display:none}a{text-decoration:none}}
    </style></head><body id="top">'''
    document += f'''<header class="hero"><div class="kicker">AI 실행 결과 발표 대회 / B COMEDY REBOOT V3</div><h1>새로운 다섯 이야기.<br>웃음은 사건에서.</h1><p>기존 완성 1번 영상은 그대로 두고, 신규 5안을 서로 다른 갈등과 반전으로 다시 구성했습니다. 아래 그림은 각 컷의 첫 프레임이며, 컷 설명은 그 뒤에 일어날 동작입니다.</p><span class="status">{status_text} · 5안 / {count}컷 · 영상 생성 없음</span><p class="note">정지 이미지와 콘티를 검토한 기획 패키지입니다. 실제 영상의 연속 동작·음성·관객 반응을 검증한 결과가 아닙니다. 행사 자막과 대사는 후속 편집 정보로 분리했습니다.</p></header><nav class="nav">{nav}</nav><main><div class="summary">{''.join(summary)}</div>{''.join(sections)}<section class="notes"><h2>제작·검수 기록</h2><p>사내 시청과 16:9는 제작 가정입니다. 행사 세부 일시·장소·참석 방법은 미확정이므로 넣지 않았습니다. 기존 C01 최종 영상 및 원자료는 보존했습니다. Flow 자동 생성 예약은 일시정지 상태입니다.</p><p><a href="storyboards.json">전체 콘티 JSON</a><a href="scene_manifest.json">이미지·컷 매핑과 프롬프트</a><a href="review_summary.json">검수 처리 기록</a><a href="research_notes.md">qrew·행사 근거</a><a href="delivery_status.json">완료 상태</a></p></section></main><dialog id="viewer"><img id="full" alt="컷 첫 프레임 확대"><footer><span id="caption"></span><button id="close">닫기 ×</button></footer></dialog><script>const viewer=document.querySelector('#viewer'),full=document.querySelector('#full'),caption=document.querySelector('#caption');document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{{full.src=button.dataset.image;caption.textContent=button.dataset.caption;viewer.showModal();}}));document.querySelector('#close').onclick=()=>viewer.close();viewer.addEventListener('click',e=>{{if(e.target===viewer)viewer.close();}});</script></body></html>'''
    (ROOT / "index.html").write_text(document, encoding="utf-8", newline="\n")
    print(json.dumps({"concepts":len(concepts),"cuts":count,"html":"index.html","manifest_images":len(images)}, ensure_ascii=False))

if __name__ == "__main__":
    main()
